const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    const kyiv = ee.Geometry.Point([30.5234, 50.4501]).buffer(20000); // 20km buffer around Kyiv center
    const jan2022 = ee.Filter.date('2022-01-01', '2022-01-31');
    const mar2022 = ee.Filter.date('2022-03-01', '2022-03-31');
    const collection = 'NOAA/VIIRS/DNB/MONTHLY_V1/VCMCFG';

    // 2. Data Acquisition & Check
    const colJan = ee.ImageCollection(collection).filter(jan2022).filterBounds(kyiv);
    const colMar = ee.ImageCollection(collection).filter(mar2022).filterBounds(kyiv);

    const janSize = colJan.size().getInfo();
    const marSize = colMar.size().getInfo();

    if (janSize === 0 || marSize === 0) {
        console.log(`Image count Jan 2022: ${janSize}`);
        console.log(`Image count Mar 2022: ${marSize}`);
        console.log('C1: Empty Collection');
        return;
    }

    const imgJan = colJan.first().select('avg_rad');
    const imgMar = colMar.first().select('avg_rad');

    // 3. Processing & Calculation
    const reducer = ee.Reducer.mean().combine({
        reducer2: ee.Reducer.count(),
        sharedInputs: true
    });

    const statsJan = imgJan.reduceRegion({
        reducer: reducer,
        geometry: kyiv,
        scale: 1000,
        maxPixels: 1e9
    }).getInfo();

    const statsMar = imgMar.reduceRegion({
        reducer: reducer,
        geometry: kyiv,
        scale: 1000,
        maxPixels: 1e9
    }).getInfo();

    // 4. Validation & Final Answer
    const radJan = statsJan['avg_rad_mean'];
    const pixelsJan = statsJan['avg_rad_count'];
    const radMar = statsMar['avg_rad_mean'];
    const pixelsMar = statsMar['avg_rad_count'];

    if (pixelsJan === 0 || pixelsMar === 0) {
        console.log(`Valid pixels Jan 2022: ${pixelsJan}`);
        console.log(`Valid pixels Mar 2022: ${pixelsMar}`);
        console.log('C2: No Valid Pixels');
        return;
    }

    if (radJan === null || radMar === null) {
        console.log('Calculation resulted in null values.');
        console.log('C3: Calculation Failure');
        return;
    }

    console.log(`January 2022 Mean Radiance: ${radJan.toFixed(2)} (Pixels: ${pixelsJan})`);
    console.log(`March 2022 Mean Radiance: ${radMar.toFixed(2)} (Pixels: ${pixelsMar})`);

    if (radMar < radJan) {
        console.log('A');
    } else {
        console.log('B');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE().catch(e => {
    console.error(`An error occurred: ${e}`);
    console.log('D');
});
